const x=$input.first().json||{};
const kind=String(x.pipeline_kind||'').trim();
const permission=String(x.requested_permission||'EXECUTE').toUpperCase();
const yellow=x.yellow_authorized===true;
const plans={
  knowledge_refinery:['SOURCE','DISTILL','REPRODUCE','FIX','RUBY_VERIFY','RETAIN'],
  knowledge_refinery_v2:['RESEARCH','UNDERSTAND','CODE','DEBUG','BUILD','CREATE','RULE','FORMULA','RUBY_VERIFY','RETAIN'],
  parallel_agents:['PLAN','FAN_OUT','COLLECT','MERGE','RUBY_VERIFY','RETAIN'],
  one_pass_refinery:['CLONES','RESEARCH','SANDBOX','FIX','RUBY_VERIFY','RETAIN'],
  runtime_x10:['FAN_OUT_10','COLLECT','N8N_PREAUDIT','GITHUB_AUDIT','YELLOW_GATE','RUBY_VERIFY','RETAIN']
};
const stages=plans[kind]||[];
const valid=Boolean(String(x.task_id||'').trim())&&Boolean(String(x.idempotency_key||'').trim())&&stages.length>0;
const consequential=['WRITE','EXECUTE','DANGEROUS'].includes(permission);
const allowed=valid && (!consequential || yellow);
return [{json:{
  schema:'OGENIC_N8N_VIOLET_PIPELINE_V1',
  ok:allowed,
  task_id:String(x.task_id||'').slice(0,180),
  oge:String(x.oge||'').toUpperCase().slice(0,32),
  pipeline_kind:kind,
  stages,
  current_stage:allowed?stages[0]:null,
  execution_allowed:allowed,
  yellow_authorized:yellow,
  requested_permission:permission,
  retry_policy:'NO_HIDDEN_RETRY',
  provider_fallback:'DENIED_WITHIN_ATTEMPT',
  ruby_verification_required:true,
  green_retention_allowed:false,
  reason:!valid?'INVALID_PIPELINE_ENVELOPE':(consequential&&!yellow?'YELLOW_AUTHORIZATION_REQUIRED':'PIPELINE_READY'),
  authority:{violet:'ORCHESTRATION_SEMANTICS',n8n:'BOUNDED_WORKFLOW_GRAPH',yellow:'EXECUTION_AUTHORITY',ruby:'VERIFY',green:'RETAIN_VERIFIED_ONLY'}
}}];
